data.논블로킹-방식의-동기-synchronization-예제#논블로킹 방식의:
논블로킹 방식으로 동기연산을 수행하려면 어떻게 해야할까요? callee 측의 작업이 오래 걸리는 작업입니다. 그런데 caller 측에서는 블로킹이 일어나지 않아야 합니다. 맞습니다. 이런 경우 callee 측의 작업을 별도의 스레드에서 수행하고 이 별도의 스레드가 끝났는지를 주기적으로 체크합니다. 그리고 작업이 끝난 것을 확인했을 때 연산 결과값을 이용해서 다음 작업을 수행합니다. 별도의 스레드가 끝났는지 주기적으로 체크하는 동안에는 다른 작업을 수행하게 될 수 있기에 논블로킹이라고 부릅니다.예제는 아래와 같습니다.
package io.chagchagchag.example.foobar.concurrent.sync_async;
import java.time.LocalTime;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import lombok.extern.slf4j.Slf4j;
@Slf4j
public class SyncNonBlockingExample {
  public static void main(String [] args) throws InterruptedException, ExecutionException {
    log.info("(start) main function " + LocalTime.now());
    var count = 1;
    Future<Integer> job = doLongDelayJob();
    while(!job.isDone()){
      log.info(String.format("대기 중... %s", count++)); // 대기 중에 counting 연산을 수행
      Thread.sleep(100);
    }
    var total = job.get() + 1;
    assert total == 1112;
    log.info("(end) main function " + LocalTime.now());
  }
  public static Future<Integer> doLongDelayJob(){
    var executor = Executors.newSingleThreadExecutor();
    try{
      return executor.submit(() -> {
        long start = System.currentTimeMillis();
        while(true){
          long delay = System.currentTimeMillis() - start;
          if(delay > 1000) break;
        }
        return 1111;
      });
    }
    catch (Exception e){
      e.printStackTrace();
      throw new RuntimeException("ERROR");
    }
    finally {
      executor.shutdown();
    }
  }
}
