data.논블로킹-방식의-비동기-synchronization-예제#논블로킹 방식의:
블로킹 방식의 비동기(Asynchronization) 예제에서는 caller 가 callee 측의 연산의 결과값을 알아야 할 필요가 없음에도 caller 가 블로킹되고 있었습니다.그렇다면 caller 가 블로킹되지 않도록 논블로킹 방식으로 callee 를 호출하려면 어떻게 해야할까요? 그렇습니다. 별도의 스레드에서 callee 를 호출하고 caller 는 자신의 작업을 계속하면 됩니다.예제는 아래와 같습니다.
package io.chagchagchag.example.foobar.concurrent.sync_async;
import java.time.LocalTime;
import java.util.concurrent.Executors;
import java.util.function.Consumer;
import lombok.extern.slf4j.Slf4j;
@Slf4j
public class AsyncNonBlockingExample {
  public static void main(String [] args){
    log.info("(start) main function " + LocalTime.now());
    execLongDelayJob(i -> {
      var result = 1 + i;
      assert result == 1112;
      log.info("result = {}", result);
    });
    log.info("(end) main function " + LocalTime.now());
  }
  public static void execLongDelayJob(Consumer<Integer> callback){
    var executor = Executors.newSingleThreadExecutor();
    try{
      executor.submit(()->{
        long start = System.currentTimeMillis();
        while(true){
          long delay = System.currentTimeMillis() - start;
          if(delay > 1000) break;
        }
        callback.accept(1111);
        log.info("작업이 끝났어요~!!! --- " + LocalTime.now());
        return 1111;
      });
    }
    catch (Exception e){
      e.printStackTrace();
      throw new RuntimeException("ERROR");
    }
    finally {
      executor.shutdown();
    }
  }
}
