      byteBuffer.flip();
      bufferLog("읽기 전환(Flip)", byteBuffer);
      byteBuffer.rewind();
      bufferLog("첫 위치로 전환(rewind)", byteBuffer);
      log.info("buffer = {}", StandardCharsets.UTF_8.decode(byteBuffer));
      bufferLog("Buffer연산 없이 decode 수행", byteBuffer);
