data.publisher-subscriber-코드에서-threadlocal-을-:
Context 에서는 ThreadLocal 을 사용불가능합니다. ThreadLocal 은 하나의 스레드에 값을 저장하고 이 스레드 안에서 어디서든지 접근 가능한 key,value 쌍을 의미합니다.Project Reactor 의 Publisher, Subscriber 는 어떤 Thread 에서 실행되다가 다시 다른 Thread에서 실행되고 하는 작업들이 내부적으로 반복되기 때문에 ThreadLocal 에 접근하는 것이 불가능하고, Project Reactor 에서도 ThreadLocal 에 접근할 수 있는 방법을 따로 제공해주지 않고 있습니다. 아래의 예제는 Publisher, Subscriber 내에서 ThreadLocal 내의 값에 접근할 수 있는지를 체크하는 예제입니다.출력결과를 보면 Publishser, Subscriber 에서는 ThreadLocal 값을 제대로 읽어오지 못한다는 사실을 알수 있습니다. main 스레드가 아닌 다른 스레드에서 실행되기 때문입니다. 출력결과의 로그에서 보이는 single-1 , parallel-1 , boundedElastic-1 은 스레드 명인데, 이렇게 ThreadLocal 이 생성된 스레드가 아닌 다른 스레드에서 실행되기 때문에 ThreadLocal 값을 제대로 읽어오지 못합니다.
package io.chagchagchag.example.foobar.spring_webflux.context;
import lombok.SneakyThrows;
import lombok.extern.slf4j.Slf4j;
import reactor.core.publisher.Flux;
import reactor.core.scheduler.Schedulers;
@Slf4j
public class JavaThreadLocal_Example {
  @SneakyThrows
  public static void main(String[] args) {
    ThreadLocal<String> threadLocal = new ThreadLocal<>();
    threadLocal.set("배고파요");
    Flux.create(fluxSink -> {
      log.info("threadLocal : " + threadLocal.get());
      fluxSink.next(5);
    })
    .publishOn(Schedulers.parallel())
    .map(v -> {
      log.info("threadLocal : " + threadLocal.get());
      return v;
    })
    .publishOn(Schedulers.boundedElastic())
    .map(v -> {
      log.info("threadLocal : " + threadLocal.get());
      return v;
    })
    .subscribeOn(Schedulers.single())
    .subscribe();
    Thread.sleep(2000);
  }
}
