현재 Publisher 를 다른 Publisher 와 합치는 연산을 수행합니다. 위의 그림을 설명해보면, 바로 앞의 Publisher 가 onComplete 를 전파하면 바로 다음 Publisher 를 subscribe() 합니다.그림을 보면 Publisher 두개를 합치는 도중에 각각의 Publiser 의 onNext 연산에 대한 순서가 각각의 요소에 대해 지켜지고 있는 것을 확인 가능합니다.
import java.time.Duration;
import lombok.SneakyThrows;
import lombok.extern.slf4j.Slf4j;
import reactor.core.publisher.Flux;
@Slf4j
public class ConcatExample1 {
  @SneakyThrows
  public static void main(String[] args) {
    var flux1 = Flux.range(1,3)
        .doOnSubscribe(v -> {
          log.info("doOnSubscribe flux#1");
        })
        .delayElements(Duration.ofMillis(100));
    var flux2 = Flux.range(11, 3)
        .doOnSubscribe(v -> {
          log.info("doOnSubscribe flux#2");
        })
        .delayElements(Duration.ofMillis(100));
    Flux.concat(flux1, flux2)
        .doOnNext(v -> {log.info("doOnNext " + v);})
        .subscribe();
    Thread.sleep(2000);
  }
}
